import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = int(next(iterator))
        b = int(next(iterator))

        if a == 1:
            if (n - 1) % b == 0 and n >= 1:
                results.append("Yes")
            else:
                results.append("No")
        else:
            found = False
            curr = 1
            while curr <= n:
                if (n - curr) % b == 0:
                    found = True
                    break
                curr *= a

            if found:
                results.append("Yes")
            else:
                resultsappend("No")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
